      "most_likely_effort": 2
    },
    {
      "activity_id": "A1.2",
      "activity_name": "Write migration guide",
      "activity_description": "Author the step-by-step migration guide covering CLI, server, modules, configuration, and known incompatibilities.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A1.3",
      "activity_name": "Document custom module porting procedure",
      "activity_description": "Describe how to recompile/repackage custom modules against the 1.1 module SPI, with worked examples.",
      "most_likely_effort": 2
    },
