      "most_likely_effort": 2
    },
    {
      "activity_id": "A2.1",
      "activity_name": "Design Pig integration with XD",
      "activity_description": "Decide module type, parameter mapping, and how Pig scripts are submitted/executed from an XD stream.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A2.2",
      "activity_name": "Implement sample Pig script",
