      "activity_id": "A2.3",
      "activity_name": "Create sample XD configuration for Pig",
      "activity_description": "Provide stream definitions (e.g., file → pigjob → log) and any required module jars.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A2.4",
      "activity_name": "Document Pig sample usage",
      "activity_description": "Write a short 'Getting Started with Pig in XD' section, including prerequisites and how to run the sample.",
      "most_likely_effort": 1
    },
