      "most_likely_effort": 1
    },
    {
      "activity_id": "A4.1",
      "activity_name": "Provision Windows EC2 AMI",
      "activity_description": "Create/configure a Windows Server AMI with JDK, Git, and XD prerequisites installed.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A4.2",
      "activity_name": "Configure acceptance test environment on Windows",
      "activity_description": "Install XD, prepare test data, and configure the acceptance-test runner on the Windows instance.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A4.3",
      "activity_name": "Adapt acceptance tests for Windows",
      "activity_description": "Adjust shell scripts, path handling, and process-management assumptions so the existing acceptance tests pass on Windows.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A4.4",
      "activity_name": "Set up Windows CI build",
      "activity_description": "Create a Jenkins job (or equivalent) that launches the Windows EC2 instance, runs the adapted acceptance tests, and reports results.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A5.1",
      "activity_name": "Design Spark Streaming integration architecture",
      "activity_description": "Define how Spark Streaming jobs map to XD processors, including receiver/DStream lifecycle, checkpointing, and deployment modes (local/cluster).",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A5.2",
      "activity_name": "Implement Java/Java 8 Lambda version",
      "activity_description": "Build the processor implementation and supporting SPI in Java, using Java 8 Lambdas where appropriate.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A5.3",
      "activity_name": "Implement Scala version",
      "activity_description": "Provide a Scala-flavored processor that demonstrates idiomatic Scala usage and reuses the Java implementation where reasonable.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A5.4",
      "activity_name": "Write tests for Spark Streaming processors",
      "activity_description": "Unit tests with a local SparkContext and at least one integration test against a running Spark cluster.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A5.5",
      "activity_name": "Document Spark Streaming processors",
      "activity_description": "Add a 'Spark Streaming' chapter to the reference guide with configuration options, examples, and limitations.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A6.1",
      "activity_name": "Update copyright year in reference guide",
      "activity_description": "Change the 2014 copyright notice to 2015 in the Asciidoctor source and regenerate the PDF.",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "A7.1",
      "activity_name": "Analyze SI Kafka vs XD Kafka differences",
      "activity_description": "Diff the XD Kafka adapter against the current SI Kafka adapter to enumerate required backports.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A7.2",
      "activity_name": "Backport XD Kafka changes to SI Kafka",
      "activity_description": "Port XD-specific Kafka extensions (codecs, partition selectors, etc.) onto the SI Kafka codebase.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A7.3",
      "activity_name": "Upgrade SI Kafka dependency to GA release",
      "activity_description": "Bump the version in the build, resolve any API/dependency changes, and recompile affected modules.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A7.4",
      "activity_name": "Test Kafka integration in XD",
      "activity_description": "Run the Kafka source/processor/sink integration tests against a real broker to verify end-to-end behavior.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A7.5",
      "activity_name": "Update Kafka-related documentation",
      "activity_description": "Reflect the new Kafka GA version and any configuration changes in the reference guide.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A8.1",
      "activity_name": "Update SHDP dependency to GA release",
      "activity_description": "Change the SHDP version in the Gradle build and resolve any transitive dependency conflicts.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A8.2",
      "activity_name": "Test SHDP integration",
      "activity_description": "Run the SHDP-related integration tests (HDFS, YARN) to confirm nothing regressed.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A8.3",
      "activity_name": "Update SHDP-related documentation",
      "activity_description": "Update version references and any new configuration options in the reference guide.",
      "most_likely_effort": 0.5
    }
  ],
  "reported_total": {
    "most_likely_effort": 51
  }
}
